/// <summary>
/// MPJ_5013 ExciseRegisterEntry
/// UI builder required for validating 
/// </summary>
public class METUpdateExciseRegisterUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField salesidField, transferIdDialogField;

}

Method.Source:
    /// <summary>
    /// MPJ_5013 ExciseRegisterEntry
    /// Post build maps the dialog fields to contract
    /// </summary>
     public void postBuild()
    {
        super();
     
        // get references to dialog controls after creation
        salesidField = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METUpdateExciseRegisterContract, parmSalesId));

        transferIdDialogField = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METUpdateExciseRegisterContract, parmTransferId));

        
    }

    /// <summary>
    /// MPJ_5013 ExciseRegisterEntry
    /// postRun allows validation and hiding of methods
    /// </summary>
    public void postRun()
    {
        super();
     
        // register overrides for form control events
        salesidField.registerOverrideMethod(methodstr(FormStringControl, validate),
                methodstr(METUpdateExciseRegisterUIBuilder, validateSalesId), this);

        salesidField.registerOverrideMethod(methodstr(FormStringControl, lookup),
                methodstr(METUpdateExciseRegisterUIBuilder, lookupSalesOrder), this);

        //Transfer Order
        transferIdDialogField.registerOverrideMethod(methodStr(FormStringControl, validate),
                                    methodStr(METUpdateExciseRegisterUIBuilder, validateTransferId),
                                    this);

        transferIdDialogField.registerOverrideMethod(methodStr(FormStringControl, lookup),
                                    methodStr(METUpdateExciseRegisterUIBuilder, lookupTransferOrder),
                                    this);

    }

    /// <summary>
    /// Validating Sales Id
    /// </summary>
    /// <param name = "_salesidField"> Sales Id</param>
    /// <returns>true or false</returns>
    public boolean validateSalesId(FormStringControl _salesidField)
    {
        SalesTable  salesTable;

        select firstonly SalesId,SalesStatus from salesTable where salesTable.SalesId == _salesidField.valueStr();
        if (salesTable.SalesStatus != SalesStatus::Invoiced)
        {
            error("@MET:SalesOrderIsNotInvoiced");
            return false;
        }
  
        return true;
    }

    /// <summary>
    /// Validate Transfer Id
    /// </summary>
    /// <param name = "_transferIdField">Transfer Id Control</param>
    /// <returns>true if valid</returns>
    public boolean validateTransferId(FormStringControl _transferIdField)
    {
        InventTransferTable  InventTransferTable;

        select firstonly transferId,transferStatus from InventTransferTable where InventTransferTable.TransferId == _transferIdField.valueStr();
        if (InventTransferTable.TransferStatus != InventTransferStatus::Received)
        {
            error(strFmt('Transfer Order - %1 is not Received',_transferIdField.valueStr()));
            return false;
        }
  
        return true;
    }

    /// <summary>
    /// Lookup for Transfer ORder
    /// </summary>
    /// <param name = "_formStringControl">Transfer Id Controle</param>
    public void lookupTransferOrder(FormStringControl _formStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbds_InventTransferTable;
        SysTableLookup          sysTableLookup;
        QueryBuildRange         qbr;

        if (_formStringControl != null)
        {
            // Create an instance of SysTableLookup with
            // the current calling form control.

            sysTableLookup = SysTableLookup::newParameters(tablenum(InventTransferTable), _formStringControl);
            sysTableLookup.addLookupfield(fieldnum(InventTransferTable, TransferId), true);
            sysTableLookup.addLookupfield(fieldnum(InventTransferTable, InventLocationIdFrom),false);
            sysTableLookup.addLookupfield(fieldnum(InventTransferTable, InventLocationIdTo),false);
            
            qbds_InventTransferTable = query.addDataSource(tableNum(InventTransferTable));
            
            qbr = qbds_InventTransferTable.addRange(fieldNum(InventTransferTable,TransferStatus));
            qbr.value(queryValue(InventTransferStatus::Received));
            sysTableLookup.parmUseLookupValue(false);

            sysTableLookup.parmQuery(query);

            // Perform the lookup.
            sysTableLookup.performFormLookup();

        }
    }

    /// <summary>
    /// Lookup for sales order
    /// </summary>
    /// <param name = "_formStringControl">Sales Order Id control</param>
    public void lookupSalesOrder(FormStringControl _formStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbds_SalesTable;
        SysTableLookup          sysTableLookup;
        QueryBuildRange         qbr;

        if (_formStringControl != null)
        {
            // Create an instance of SysTableLookup with
            // the current calling form control.

            sysTableLookup = SysTableLookup::newParameters(tablenum(SalesTable), _formStringControl);
            sysTableLookup.addLookupfield(fieldnum(SalesTable, SalesId), true);
            sysTableLookup.addLookupfield(fieldnum(SalesTable, CustAccount),false);
            sysTableLookup.addLookupfield(fieldnum(SalesTable, DeliveryName),false);
            
            qbds_SalesTable = query.addDataSource(tableNum(SalesTable));
            
            qbr = qbds_SalesTable.addRange(fieldNum(SalesTable,SalesStatus));
            qbr.value(queryValue(SalesStatus::Invoiced));
            sysTableLookup.parmUseLookupValue(false);

            sysTableLookup.parmQuery(query);

            // Perform the lookup.
            sysTableLookup.performFormLookup();

        }
    }
